import{_ as t,o as n,c as a,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Persistent connections","description":"","frontmatter":{},"headers":[],"relativePath":"bull/patterns/persistent-connections.md","filePath":"bull/patterns/persistent-connections.md","lastUpdated":1737825266000}'),s={name:"bull/patterns/persistent-connections.md"};function i(r,e,c,l,h,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="persistent-connections" tabindex="-1">Persistent connections <a class="header-anchor" href="#persistent-connections" aria-label="Permalink to &quot;Persistent connections&quot;">​</a></h1><p>A crucial feature for a subsystem in a microservice architecture is that it should automatically handle disconnections from other services and keep these connections alive for as long as the service is running.</p><p>For example, if your service has a connection to a database, and the connection to said database breaks, you would like that service to handle this disconnection as gracefully as possible and as soon as the database is back online continue to work without human intervention.</p><p>Since Bull relies on <strong>ioredis</strong> for accessing Redis, the default is auto-reconnect forever. This behaviour can be customized but most likely the default is the best setting currently: <a href="https://github.com/luin/ioredis#auto-reconnect" target="_blank" rel="noreferrer">https://github.com/luin/ioredis#auto-reconnect</a></p><p>In the context of Bull, we have normally two different cases that are handled differently.</p><h3 id="workers" tabindex="-1">Workers <a class="header-anchor" href="#workers" aria-label="Permalink to &quot;Workers&quot;">​</a></h3><p>A worker is consuming jobs from the queue as fast as it can. If it loses the connection to Redis we want the worker to &quot;wait&quot; until Redis is available again. For this to work we need to understand an important setting in our Redis options (which are handled by ioredis):</p><h4 id="maxretriesperrequest" tabindex="-1"><code>maxRetriesPerRequest</code> <a class="header-anchor" href="#maxretriesperrequest" aria-label="Permalink to &quot;`maxRetriesPerRequest`&quot;">​</a></h4><p>This setting tells the ioredis client how many times to try a command that fails before throwing an error. So even though Redis is not reachable or offline, the command will be retried until this situation changes or the maximum number of attempts is reached.</p><p>In Bull we set this setting to null both for the &quot;bclient&quot; and &quot;eclient&quot; connections, which are used for the workers and events respectively.</p><p>This guarantees that the workers will keep processing forever as long as there is a working connection. If you create a Redis client manually, Bull will throw an exception if this setting is not set to null.</p><h3 id="queue" tabindex="-1">Queue <a class="header-anchor" href="#queue" aria-label="Permalink to &quot;Queue&quot;">​</a></h3><p>A simple Queue instance used for managing the queue such as adding jobs, pausing, using getters, etc. usually has different requirements from the worker.</p><p>For example, say that you are adding jobs to a queue as the result of a call to an HTTP endpoint. The caller of this endpoint cannot wait forever if the connection to Redis happens to be down when this call is made.</p><p>Therefore the <code>maxRetriesPerRequest</code> setting should either be left at its default (which currently is 20) or set it to another value, maybe 1 so that the user gets an error quickly and can retry later.</p>',15)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
